base_css:
/* American Banker x TCS Signature Collection (matches the reference landing page) */
body { font-family: Roboto, Arial, sans-serif; color: #363636; background: #ffffff; }

/* Header: logo + uppercase menu, laid over the hero like the original */
.tcs-header { position: absolute; top: 0; left: 0; right: 0; z-index: 5; background: transparent; border-bottom: 0; }
.tcs-header .lp-nav-inner { max-width: 1320px; padding-top: 28px; padding-bottom: 28px; }
.tcs-logo img { height: 42px; max-width: 270px; }
.tcs-menu { justify-content: flex-end; column-gap: 36px; font-family: Poppins, sans-serif; font-size: 15px; font-weight: 500; text-transform: uppercase; color: #1c1b1b; }
.tcs-menu a { padding: 4px 0; }
.tcs-menu a:hover { color: #1969a0; }

/* Hero: kicker + big headline, photo in a blue circle on the right, wave divider at the bottom */
.tcs-hero { padding: 230px 0 120px; background-color: #ffffff;
  background-image: url("https://valasysb2bmarketing.com/AB-Tata-TCS-Signature-Collection-Article-List-Program/images/banner/style2/banner-right.png"), linear-gradient(180deg, #ffffff 0%, #ffffff 55%, #eaf6fe 100%);
  background-repeat: no-repeat, no-repeat; background-position: right top, center; background-size: auto 520px, cover; }
.tcs-hero-copy { max-width: 700px; }
.tcs-kicker { font-family: Poppins, sans-serif; font-size: 18px; font-weight: 700; color: #1969a0; text-transform: uppercase; margin: 0 0 4px; }
.tcs-title { font-family: Poppins, sans-serif; font-size: 40px; line-height: 1.12; font-weight: 700; color: #1c1b1b; margin: 0; }

/* Main: copy + articles on the left, the form box on the right */
.tcs-main { padding: 10px 0 40px; }
.tcs-row { justify-content: space-between; align-items: flex-start; gap: 40px; }
.tcs-left { flex: 0 0 calc(58% - 20px); }
.tcs-right { flex: 0 0 calc(33% - 20px); padding-top: 90px; }
.tcs-sponsor { flex-direction: column; align-items: flex-start; justify-content: flex-start; gap: 2px; margin: 0 0 30px; }
.tcs-sponsor .lp-sponsor-label { font-size: 12px; letter-spacing: 2px; font-weight: 800; color: #2e1764; text-transform: uppercase; }
.tcs-sponsor img { height: 36px; }
.tcs-h2 { font-family: Poppins, sans-serif; font-size: 36px; line-height: 0.95; font-weight: 700; color: #1c1b1b; margin: 0 0 28px; }
.tcs-p { font-family: Roboto, sans-serif; font-size: 16px; line-height: 1.7; color: #363636; margin: 0 0 22px; }
.tcs-urgency { background-color: #001a39; color: #ffffff; border-radius: 5px; font-family: Lato, Roboto, sans-serif; font-size: 16px; font-weight: 700; line-height: 26px; padding: 17px; max-width: 640px; margin: 28px 0 0; }
.tcs-author { display: flex; align-items: center; gap: 22px; margin-top: 24px; font-family: Lato, Roboto, sans-serif; }
.tcs-author img { width: 72px; height: 72px; object-fit: cover; display: block; }
.tcs-author-name { color: #333333; font-size: 18px; font-weight: 600; line-height: 24px; margin: 0; }
.tcs-author-role { color: #333333; font-size: 16px; line-height: 1.6; margin: 0; }
.tcs-collection-title { font-family: Georgia, serif; font-size: 20px; font-weight: 700; color: #121212; margin: 48px 0 26px; }

/* Article cards, 2 per row like the original */
.tcs-cards { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 24px 28px; }
.tcs-cards .lp-card { border: 1px solid #808080; border-radius: 8px; }
.tcs-cards .lp-card > img { aspect-ratio: 302 / 175; border-radius: 8px 8px 0 0; }
.tcs-cards .lp-card-body { padding: 16px 16px 10px; }
.tcs-cards .lp-card-label { font-family: Roboto, sans-serif; font-size: 15px; font-weight: 400; letter-spacing: 0; color: #333333; margin: 0 0 4px; }
.tcs-cards .lp-card h3 { font-family: Roboto, sans-serif; font-size: 22px; line-height: 30px; font-weight: 700; color: #121212; margin: 0 0 16px; }
.tcs-cards .lp-card-by { font-family: Lato, Arial, sans-serif; font-size: 16px; font-weight: 700; letter-spacing: .8px; color: #333333; margin: 0 0 8px; }
.tcs-cards .lp-card-by a { color: #1a73e8; text-decoration: none; }

/* Form box: bright blue, placeholder-only fields, yellow button */
.tcs-formbox { background-color: #00aff7; padding: 30px 30px 35px; }
.tcs-formbox .form-card { background: transparent; border: 0; border-radius: 0; box-shadow: none; padding: 0; position: static; }
.tcs-formbox .form-card h2 { font-family: Poppins, sans-serif; color: #ffffff; font-size: 14.8px; line-height: 1.6; font-weight: 700; text-transform: uppercase; margin: 0 0 10px; }
.tcs-formbox .fields { gap: 4px; }
.tcs-formbox .field label { display: none; }
.tcs-formbox .field input, .tcs-formbox .field select { height: 35px; padding: 3px 16px; border: 0; border-radius: 0; background-color: #f1f6fc; color: #363636; font-size: 15px; }
.tcs-formbox .field input::placeholder { color: #9a9a9a; }
.tcs-formbox .field input:focus, .tcs-formbox .field select:focus { box-shadow: 0 0 0 2px #001a39; }
.tcs-formbox .error-msg { color: #001a39; font-weight: 700; }
.tcs-formbox .consent { color: #ffffff; font-size: 13px; line-height: 18px; margin-top: 12px; }
.tcs-formbox .consent .check { color: #ffffff; font-size: 13px; }
.tcs-formbox .consent p { margin: 0 0 14px; }
.tcs-formbox .consent a, .tcs-privacy a { color: #ffffff; text-decoration: underline; }
.tcs-formbox .btn { width: auto; background-color: #fce300; color: #000000; font-family: Poppins, sans-serif; font-size: 14px; font-weight: 500; text-transform: uppercase; padding: 13px 29px; border-radius: 3px; margin-top: 10px; }
.tcs-formbox .form-error { color: #001a39; font-weight: 700; }
.tcs-privacy { color: #ffffff; font-size: 13px; line-height: 18px; margin: 46px 0 0; }

/* About + footer (blue gradient band; its curved top edge is the "Swoosh" shape divider) */
.tcs-about { padding: 30px 0 40px; }
.tcs-about-title { font-family: Poppins, sans-serif; font-size: 16px; font-weight: 600; color: #1c1b1b; margin: 0 0 24px; }
.tcs-footer { background-color: #015eea; background-image: linear-gradient(90deg, #015eea 0%, #016fed 50%, #00a7f6 100%); padding: 62px 0 26px; }
.tcs-footer-inner { display: grid; grid-template-columns: 1fr 1fr; align-items: center; gap: 20px; }
.tcs-copy { margin: 0; color: #ffffff; font-size: 16px; }
.tcs-footer-logo { width: 150px; height: auto; display: block; }

/* Header turns white and sticks to the top once the page scrolls (script in Code > JavaScript) */
.tcs-header.tcs-scrolled { position: fixed; background: #ffffff; box-shadow: 0 6px 24px rgba(15, 23, 42, .1); }
.tcs-header.tcs-scrolled .lp-nav-inner { padding-top: 14px; padding-bottom: 14px; }

/* Back-to-top button (hidden near the top of the page by the same script) */
.tcs-top { position: fixed; right: 34px; bottom: 34px; z-index: 6; width: 44px; height: 44px; border-radius: 50%; background-color: #1a62e6; color: #ffffff; display: flex; align-items: center; justify-content: center; box-shadow: 0 6px 16px rgba(0, 0, 0, .2); transition: opacity .2s, transform .2s; }
.tcs-top:hover { transform: translateY(-2px); }
.tcs-top svg { width: 20px; height: 20px; }
.tcs-top.tcs-top-hidden { opacity: 0; pointer-events: none; }

/* Tablet and phone */
@media (max-width: 991px) {
  .tcs-hero { background-size: auto 340px, cover; padding-top: 200px; }
  .tcs-hero-copy { max-width: 60%; }
  .tcs-title { font-size: 32px; }
  .tcs-menu { column-gap: 20px; font-size: 13px; }
}
@media (max-width: 767px) {
  .tcs-header { position: static; }
  .tcs-header .lp-nav-inner { padding-top: 16px; padding-bottom: 12px; }
  .tcs-hero { padding: 40px 0 90px; background-image: linear-gradient(180deg, #ffffff 0%, #eaf6fe 100%); }
  .tcs-hero-copy { max-width: none; }
  .tcs-title { font-size: 28px; }
  .tcs-h2 { font-size: 28px; line-height: 1.15; }
  .tcs-right { padding-top: 0; }
  .tcs-cards { grid-template-columns: 1fr; }
  .tcs-footer { padding: 46px 0 22px; }
  .tcs-footer-inner { grid-template-columns: 1fr; justify-items: center; text-align: center; }
  .tcs-header.tcs-scrolled { position: static; box-shadow: none; background: transparent; }
  .tcs-top { right: 16px; bottom: 16px; }
}

custom_js:
// Sticky white header + back-to-top button (American Banker x TCS design)
(function () {
  var header = document.querySelector('.tcs-header'), top = document.querySelector('.tcs-top');
  function onScroll() {
    if (header) header.classList.toggle('tcs-scrolled', window.scrollY > 80);
    if (top) top.classList.toggle('tcs-top-hidden', window.scrollY < 300);
  }
  // The header is pinned while scrolling, so scroll the window itself back to the top.
  if (top) top.addEventListener('click', function (e) { e.preventDefault(); window.scrollTo({ top: 0, behavior: 'smooth' }); });
  window.addEventListener('scroll', onScroll, { passive: true });
  onScroll();
})();
